using LUMAR_ERP_API_V2.DTOs.Auth;
using LUMAR_ERP_API_V2.Services;
using Microsoft.AspNetCore.Mvc;
namespace LUMAR_ERP_API_V2.Controllers;
[ApiController, Route("auth")]
public sealed class AuthController(IAuthService service, ILogger<AuthController> logger) : ControllerBase
{
    [HttpPost("login")] public async Task<ActionResult<SessionDto>> Login(LoginDto request,CancellationToken ct){var result=await service.LoginAsync(request,ct);return result is null?Unauthorized("Invalid username or password."):Ok(result);}
    [HttpPost("mobile/customer/register")] public async Task<ActionResult<SessionDto>> RegisterMobileCustomer(MobileCustomerRegistrationDto request,CancellationToken ct){try{var result=await service.RegisterMobileCustomerAsync(request,ct);return Ok(result);}catch(ArgumentException ex){return BadRequest(ex.Message);}catch(Microsoft.Data.SqlClient.SqlException ex) when(ex.Number is 2601 or 2627){return Conflict("Username or customer already exists.");}}
    [HttpPost("mobile/employee/provision")] public async Task<ActionResult<object>> ProvisionOfficialEmployeeAccount(EmployeeProvisioningRequest request,CancellationToken ct){if (request is null){var correlationId = HttpContext.TraceIdentifier;logger.LogWarning("Employee provisioning request was null. CorrelationId={CorrelationId}", correlationId);return BadRequest(new { message = "بيانات الموظف غير صالحة.", correlationId });}var correlationId2 = HttpContext.TraceIdentifier;var employeeCodeMasked = MaskValue(request.EmployeeCode);var phoneProvided = !string.IsNullOrWhiteSpace(request.PhoneNumber);var preferredUsernameProvided = !string.IsNullOrWhiteSpace(request.PreferredUsername);logger.LogInformation("Employee provisioning request started. CorrelationId={CorrelationId} EmployeeCode={EmployeeCode} PhoneNumberProvided={PhoneNumberProvided} PreferredUsernameProvided={PreferredUsernameProvided}", correlationId2, employeeCodeMasked, phoneProvided, preferredUsernameProvided);try{var result=await service.ProvisionOfficialEmployeeAccountAsync(request,ct);return result is null ? NotFound(new { message = "لم يتم العثور على موظف بهذا الكود.", correlationId = correlationId2 }) : Ok(result);}catch(KeyNotFoundException ex){logger.LogWarning(ex, "Employee provisioning lookup failed. CorrelationId={CorrelationId}", correlationId2);return NotFound(new { message = "لم يتم العثور على موظف بهذا الكود.", correlationId = correlationId2 });}catch(ArgumentException ex){logger.LogWarning(ex, "Employee provisioning validation failed. CorrelationId={CorrelationId}", correlationId2);return BadRequest(new { message = TranslateEmployeeProvisioningError(ex.Message), correlationId = correlationId2 });}catch(Microsoft.Data.SqlClient.SqlException ex) when(ex.Number is 2601 or 2627){logger.LogWarning(ex, "Employee provisioning conflict. CorrelationId={CorrelationId}", correlationId2);return Conflict(new { message = "اسم المستخدم مستخدم مسبقاً. اختر اسماً آخر.", correlationId = correlationId2 });}catch(Exception ex){logger.LogError(ex, "Unexpected employee provisioning failure. CorrelationId={CorrelationId}", correlationId2);return StatusCode(StatusCodes.Status500InternalServerError, new { message = $"حدث خطأ في الخادم أثناء إنشاء الحساب. رقم المتابعة: {correlationId2}", correlationId = correlationId2 });}}
    [HttpPost("mobile/employee/password-setup")] public async Task<IActionResult> CompleteEmployeePasswordSetup([FromBody] PasswordSetupDto request,CancellationToken ct){var correlationId = HttpContext.TraceIdentifier;if(request is null || string.IsNullOrWhiteSpace(request.SetupToken)) return BadRequest(new { message = "رمز إعداد كلمة المرور مطلوب.", correlationId });var ok=await service.CompleteEmployeePasswordSetupAsync(request.SetupToken, request.NewPassword, request.ConfirmPassword, ct);if (!ok) {logger.LogWarning("Employee password setup failed or token expired. CorrelationId={CorrelationId}", correlationId); return BadRequest(new { message = "تعذر إعداد كلمة المرور أو الرمز غير صالح.", correlationId });}logger.LogInformation("Employee password setup completed. CorrelationId={CorrelationId}", correlationId);return NoContent();}
    [HttpPost("mobile/supplier/provision")] public async Task<ActionResult<object>> ProvisionOfficialSupplierAccount(SupplierProvisioningRequest request,CancellationToken ct){if (request is null){var correlationId = HttpContext.TraceIdentifier;logger.LogWarning("Supplier provisioning request was null. CorrelationId={CorrelationId}", correlationId);return BadRequest(new { message = "بيانات المورد غير صالحة.", correlationId });}var correlationId2 = HttpContext.TraceIdentifier;var supplierCodeMasked = MaskValue(request.SupplierCode);var phoneProvided = !string.IsNullOrWhiteSpace(request.PhoneNumber);var preferredUsernameProvided = !string.IsNullOrWhiteSpace(request.PreferredUsername);logger.LogInformation("Supplier provisioning request started. CorrelationId={CorrelationId} SupplierCode={SupplierCode} PhoneNumberProvided={PhoneNumberProvided} PreferredUsernameProvided={PreferredUsernameProvided}", correlationId2, supplierCodeMasked, phoneProvided, preferredUsernameProvided);try{var result=await service.ProvisionOfficialSupplierAccountAsync(request,ct);return result is null ? NotFound(new { message = "لم يتم العثور على مورد بهذا الكود.", correlationId = correlationId2 }) : Ok(result);}catch(KeyNotFoundException ex){logger.LogWarning(ex, "Supplier provisioning lookup failed. CorrelationId={CorrelationId}", correlationId2);return NotFound(new { message = "لم يتم العثور على مورد بهذا الكود.", correlationId = correlationId2 });}catch(ArgumentException ex) when (IsSupplierAlreadyHasAccountError(ex.Message)){logger.LogWarning(ex, "Supplier provisioning duplicate account. CorrelationId={CorrelationId}", correlationId2);return Conflict(new { message = "لدى هذا المورد حساب مسبقاً. استخدم تسجيل الدخول.", correlationId = correlationId2 });}catch(ArgumentException ex){logger.LogWarning(ex, "Supplier provisioning validation failed. CorrelationId={CorrelationId}", correlationId2);return BadRequest(new { message = TranslateSupplierProvisioningError(ex.Message), correlationId = correlationId2 });}catch(Microsoft.Data.SqlClient.SqlException ex) when(ex.Number is 2601 or 2627){logger.LogWarning(ex, "Supplier provisioning conflict. CorrelationId={CorrelationId}", correlationId2);return Conflict(new { message = "اسم المستخدم مستخدم مسبقاً. اختر اسماً آخر.", correlationId = correlationId2 });}catch(Exception ex){logger.LogError(ex, "Unexpected supplier provisioning failure. CorrelationId={CorrelationId}", correlationId2);return StatusCode(StatusCodes.Status500InternalServerError, new { message = "حدث خطأ في الخادم أثناء إنشاء الحساب. رقم المتابعة: " + correlationId2, correlationId = correlationId2 });}}
    [HttpPost("mobile/supplier/password-setup")] public async Task<IActionResult> CompleteSupplierPasswordSetup([FromBody] PasswordSetupDto request,CancellationToken ct){var correlationId = HttpContext.TraceIdentifier;if(request is null || string.IsNullOrWhiteSpace(request.SetupToken)) return BadRequest(new { message = "رمز إعداد كلمة المرور مطلوب.", correlationId });var ok=await service.CompleteSupplierPasswordSetupAsync(request.SetupToken, request.NewPassword, request.ConfirmPassword, ct);if (!ok) {logger.LogWarning("Supplier password setup failed or token expired. CorrelationId={CorrelationId}", correlationId); return BadRequest(new { message = "تعذر إعداد كلمة المرور أو الرمز غير صالح.", correlationId });}logger.LogInformation("Supplier password setup completed. CorrelationId={CorrelationId}", correlationId);return NoContent();}
    [HttpGet("me")] public async Task<ActionResult<CurrentUserDto>> Me(CancellationToken ct){var user=await service.GetCurrentUserAsync(Token,ct);return user is null?Unauthorized():Ok(user);}
    [HttpGet("account-type")] public async Task<ActionResult<AccountTypeDto>> AccountType(CancellationToken ct){var account=await service.GetAccountTypeAsync(Token,ct);return account is null?Unauthorized():Ok(account);}
    [HttpPost("logout")] public async Task<IActionResult> Logout(CancellationToken ct)=>await service.LogoutAsync(Token,ct)?NoContent():Unauthorized();
    [HttpPut("username")] public async Task<ActionResult<SessionDto>> Username(ChangeUsernameDto request,CancellationToken ct){try{var result=await service.ChangeUsernameAsync(Token,request,ct);return result is null?BadRequest("Unable to change username."):Ok(result);}catch(ArgumentException){return Conflict("Username already exists.");}}
    [HttpPut("password")] public async Task<IActionResult> Password(ChangePasswordDto request,CancellationToken ct)=>await service.ChangePasswordAsync(Token,request,ct)?NoContent():BadRequest("Unable to change password.");
    private string Token => Request.Headers.Authorization.ToString().StartsWith("Bearer ",StringComparison.OrdinalIgnoreCase)?Request.Headers.Authorization.ToString()[7..]:string.Empty;
    private static string MaskValue(string? value) => string.IsNullOrWhiteSpace(value) ? "<empty>" : value.Length <= 2 ? "*" : $"{value[..2]}***{value[^2..]}";
    private static string TranslateEmployeeProvisioningError(string message)
    {
        if (message.Contains("EmployeeCode is required", StringComparison.OrdinalIgnoreCase)) return "كود الموظف الرسمي مطلوب.";
        if (message.Contains("رقم الهاتف مطلوب", StringComparison.OrdinalIgnoreCase)) return "رقم الهاتف مطلوب للتحقق من هوية الموظف.";
        if (message.Contains("not found", StringComparison.OrdinalIgnoreCase)) return "لم يتم العثور على موظف بهذا الكود.";
        if (message.Contains("inactive", StringComparison.OrdinalIgnoreCase)) return "حساب الموظف غير نشط في المؤسسة.";
        if (message.Contains("does not match", StringComparison.OrdinalIgnoreCase) || message.Contains("رقم الهاتف لا يطابق", StringComparison.OrdinalIgnoreCase)) return "رقم الهاتف لا يطابق سجل الموظف الرسمي.";
        if (message.Contains("already exists", StringComparison.OrdinalIgnoreCase) || message.Contains("اسم المستخدم", StringComparison.OrdinalIgnoreCase)) return "اسم المستخدم مستخدم مسبقاً. اختر اسماً آخر.";
        if (message.Contains("already has an official mobile account", StringComparison.OrdinalIgnoreCase) || message.Contains("حساب مسبقاً", StringComparison.OrdinalIgnoreCase)) return "لدى هذا الموظف حساب مسبقاً. استخدم تسجيل الدخول.";
        return "بيانات الموظف غير صالحة.";
    }

    private static string TranslateSupplierProvisioningError(string message)
    {
        if (message.Contains("SupplierCode is required", StringComparison.OrdinalIgnoreCase)) return "كود المورد مطلوب.";
        if (message.Contains("رقم الهاتف مطلوب", StringComparison.OrdinalIgnoreCase)) return "رقم الهاتف مطلوب للتحقق من هوية المورد.";
        if (message.Contains("not found", StringComparison.OrdinalIgnoreCase)) return "لم يتم العثور على مورد بهذا الكود.";
        if (message.Contains("inactive", StringComparison.OrdinalIgnoreCase)) return "حساب المورد غير نشط في المؤسسة.";
        if (message.Contains("does not match", StringComparison.OrdinalIgnoreCase) || message.Contains("رقم الهاتف لا يطابق", StringComparison.OrdinalIgnoreCase)) return "رقم الهاتف لا يطابق سجل المورد الرسمي.";
        if (message.Contains("already exists", StringComparison.OrdinalIgnoreCase) || message.Contains("اسم المستخدم", StringComparison.OrdinalIgnoreCase)) return "اسم المستخدم مستخدم مسبقاً. اختر اسماً آخر.";
        if (message.Contains("already has an official mobile account", StringComparison.OrdinalIgnoreCase)
            || message.Contains("already has an account", StringComparison.OrdinalIgnoreCase)
            || message.Contains("لدى هذا المورد حساب مسبقاً", StringComparison.OrdinalIgnoreCase)
            || message.Contains("حساب مسبقاً", StringComparison.OrdinalIgnoreCase)) return "لدى هذا المورد حساب مسبقاً. استخدم تسجيل الدخول.";
        return "بيانات المورد غير صالحة.";
    }

    private static bool IsSupplierAlreadyHasAccountError(string message) =>
        message.Contains("already has an official mobile account", StringComparison.OrdinalIgnoreCase)
        || message.Contains("already has an account", StringComparison.OrdinalIgnoreCase)
        || message.Contains("لدى هذا المورد حساب مسبقاً", StringComparison.OrdinalIgnoreCase)
        || message.Contains("حساب مسبقاً", StringComparison.OrdinalIgnoreCase);
}